      sport: 'การออกกำลังกาย',
      travel: 'การท่องเที่ยว',
      date: 'เดท',
      dinner: 'ดินเนอร์',
      cafe: 'ไปคาเฟ่',
      party: 'งานปาร์ตี้',
    }

    message += `สำหรับโอกาส: ${occasionNames[occasion]}\n\n`
  }

  message += `เราพบสินค้าที่เหมาะสมกับคุณ ${filteredProducts.length} รายการ`

  return {
    message,
    recommendedProducts: filteredProducts.slice(0, 6),
    occasion,
  }
}

